// Simple Temple Data - All in one file
export interface Temple {
  id: string
  name: string
  deity: string
  description: string
  address: string
  city: string
  state: string
  latitude: number
  longitude: number
  rating: number
  image?: string
  // Phase 1 - Essential Information
  openingHours?: string
  phoneNumber?: string
  festivals?: string[]
  specialSignificance?: string
  parking?: boolean
  photographyAllowed?: boolean
}

export interface DeityCategory {
  id: string
  name: string
  icon: string
  description: string
  mantra?: string
}

export interface Festival {
  id: string
  name: string
  dateLabel: string
  description: string
}

